import{_ as l,o,c as i,ag as a}from"./chunks/framework.i8sMDeRW.js";const p=JSON.parse('{"title":"🧰 AI PM 实战工具包","description":"","frontmatter":{},"headers":[],"relativePath":"guide/06-career/pm-toolkit.md","filePath":"guide/06-career/pm-toolkit.md","lastUpdated":1782288443000}'),s={name:"guide/06-career/pm-toolkit.md"};function n(r,t,e,u,d,g){return o(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="🧰-ai-pm-实战工具包" tabindex="-1">🧰 AI PM 实战工具包 <a class="header-anchor" href="#🧰-ai-pm-实战工具包" aria-label="Permalink to &quot;🧰 AI PM 实战工具包&quot;">​</a></h1><blockquote><p>面向 AI 产品经理的日常作战工具箱 —— 立项检查、跨团队沟通、Demo 防翻车，拿来即用。</p></blockquote><hr><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#1-ai-产品立项-checklist">AI 产品立项 Checklist</a></li><li><a href="#2-跨团队沟通框架">跨团队沟通框架</a></li><li><a href="#3-ai-产品-demo-技巧">AI 产品 Demo 技巧</a></li></ol><hr><h2 id="_1-ai-产品立项-checklist" tabindex="-1">1. AI 产品立项 Checklist <a class="header-anchor" href="#_1-ai-产品立项-checklist" aria-label="Permalink to &quot;1. AI 产品立项 Checklist&quot;">​</a></h2><h3 id="_1-1-接手新-ai-产品后第一周要做的事" tabindex="-1">1.1 接手新 AI 产品后第一周要做的事 <a class="header-anchor" href="#_1-1-接手新-ai-产品后第一周要做的事" aria-label="Permalink to &quot;1.1 接手新 AI 产品后第一周要做的事&quot;">​</a></h3><blockquote><p>下列清单按优先级排列。第一周完成 ☐ 项，第二周完成 ◻ 项，存档备查 ○ 项。</p></blockquote><h4 id="day-1-2-问题确认与用户验证" tabindex="-1">Day 1-2：问题确认与用户验证 <a class="header-anchor" href="#day-1-2-问题确认与用户验证" aria-label="Permalink to &quot;Day 1-2：问题确认与用户验证&quot;">​</a></h4><ul><li>☐ <strong>确认这是真 AI 问题还是假 AI 问题</strong><ul><li>这个问题不用 AI 能解决吗？如果能，成本更低吗？</li><li>用户真正需要的是「更准的答案」还是「有答案就行」？</li><li>伪需求信号：用户说&quot;希望更智能&quot;，但追问后说不出具体场景</li></ul></li><li>☐ <strong>现有方案为什么不够好</strong><ul><li>用户现在用手工/规则/外包怎么做的？痛在哪里？</li><li>是效率问题、质量问题、还是根本做不到？</li></ul></li><li>☐ <strong>一句话价值主张</strong><ul><li>写完这句发给至少 5 个真实用户验证：&quot;我们这个功能可以帮你 ____，让你 ____&quot;</li><li>如果 3 个人以上说&quot;看不懂&quot;或&quot;不需要&quot;，回炉重造</li></ul></li><li>☐ <strong>成功指标定义（立项即定义）</strong><ul><li>核心指标 <em>1 个</em>（不要超过 3 个）：任务完成率 / 时间节省 / 收入提升</li><li>当前 baseline 值是多少？没有 baseline 的指标等于没指标</li></ul></li></ul><h4 id="day-3-4-竞品与技术调研" tabindex="-1">Day 3-4：竞品与技术调研 <a class="header-anchor" href="#day-3-4-竞品与技术调研" aria-label="Permalink to &quot;Day 3-4：竞品与技术调研&quot;">​</a></h4><ul><li>☐ <strong>竞品 AI 能力矩阵</strong><ul><li>列出 Top 3 竞品 + 2 个跨行业参考</li><li>竞品用 AI 做了什么？效果如何？（截图 + 数据）</li><li>我们差异化的点在哪里？数据优势？场景理解？成本结构？</li></ul></li><li>☐ <strong>技术方案选型</strong><ul><li>自研 vs 调用 API vs 开源微调？依据是什么？</li><li>模型选型：参数规模、推理速度、上下文长度、成本</li><li>是否需要 RAG？知识库来源是什么？更新频率？</li></ul></li><li>☐ <strong>数据可行性评估</strong><ul><li>训练/微调数据从哪里来？质量如何？标注成本？</li><li>用户数据隐私合规：数据出境？用户授权？脱敏方案？</li><li>冷启动策略：没有用户数据时怎么让模型先跑起来？</li></ul></li></ul><h4 id="day-5-7-成本、评估与风险" tabindex="-1">Day 5-7：成本、评估与风险 <a class="header-anchor" href="#day-5-7-成本、评估与风险" aria-label="Permalink to &quot;Day 5-7：成本、评估与风险&quot;">​</a></h4><ul><li>☐ <strong>成本估算 —— 必须算三笔账</strong><ul><li><strong>推理成本</strong>：每次请求的 token 消耗 × 预估调用量。GPT-4 级别模型约 $0.03-0.12/次请求，小模型 $0.001-0.01</li><li><strong>标注成本</strong>：评估集标注、bad case 回收标注、微调数据标注。按条计费 vs 按小时</li><li><strong>基建成本</strong>：GPU 实例/API 订阅/向量数据库/CDN/带宽。最低 MVP 每月至少 $500-2000</li><li><strong>成本模型要随着规模变化重新算</strong>：1000 DAU 和 100 万 DAU，成本结构完全不同</li></ul></li><li>☐ <strong>评估准备 —— 没有评估就是盲人摸象</strong><ul><li><strong>评估集</strong>：至少 200-500 条覆盖核心场景的测试用例，含 edge case (不少于 20%)</li><li><strong>Baseline</strong>：没有 AI 时的效果（规则/人工/旧模型），作为对比基准</li><li><strong>评估维度</strong>：准确率 ✓、拒绝率（该拒绝时拒绝了吗）、幻觉率、用户满意度</li><li><strong>自动评估 vs 人工评估</strong>：自动评估跑量，人工评估跑质，两者不可偏废</li></ul></li><li>☐ <strong>团队能力评估</strong><ul><li>团队之前做过 AI 产品吗？踩过哪些坑？</li><li>ML Engineer：有部署和推理优化经验吗？还是只会调 API？</li><li>谁负责 prompt 工程？谁负责评估？谁负责 bad case 分析？</li><li><strong>没有专职 AI 评估角色的团队，AI 产品质量一定崩塌</strong></li></ul></li><li>☐ <strong>风险管理 —— 列出 Top 5 风险</strong><ul><li>技术风险 1：模型幻觉导致用户体验灾难（概率：高 / 影响：灾难级）</li><li>技术风险 2：推理延迟超预期，用户流失（概率：中 / 影响：高）</li><li>产品风险 1：用户对 AI 能力过度期望（概率：高 / 影响：中）</li><li>产品风险 2：PMF 不成立，用户不需要（概率：中 / 影响：致命）</li><li>组织风险：AI 评审周期过长，错过窗口（概率：中 / 影响：中）</li><li>每个风险要有<strong>缓解措施</strong>和<strong>触发告警的阈值</strong></li></ul></li><li>☐ <strong>合规检查清单</strong><ul><li>内容安全：AI 输出的有害/偏见/违法内容如何拦截？</li><li>数据隐私：用户数据是否用于模型训练？是否获得授权？</li><li>版权风险：模型输出是否可能侵犯第三方版权？</li><li>监管合规：是否涉及深度合成/生成式 AI 备案？</li><li>未成年人保护：是否有年龄分级和内容过滤？</li></ul></li><li>☐ <strong>退出标准 —— 什么情况下应该放弃</strong><ul><li>模型效果持续 N 周达不到 baseline（建议：连续 4 周）</li><li>推理成本超过用户生命周期价值的 3 倍</li><li>用户留存率低于传统方案</li><li>合规审查不通过且无可行替代方案</li><li><strong>写进 PRD 的&quot;Not Doing&quot;清单中，明确放弃条件</strong></li><li><strong>每两周复盘一次退出条件，不要等到投入半年才决定放弃</strong></li></ul></li></ul><h3 id="_1-2-立项后第二周-checklist-快速启动" tabindex="-1">1.2 立项后第二周 Checklist（快速启动） <a class="header-anchor" href="#_1-2-立项后第二周-checklist-快速启动" aria-label="Permalink to &quot;1.2 立项后第二周 Checklist（快速启动）&quot;">​</a></h3><ul><li>◻ <strong>MVP 范围锁定</strong>：最小可行 AI 功能是什么？砍掉 50% 的 feature</li><li>◻ <strong>Prompt 基线版本</strong>：写第一版 system prompt，团队内 blind review</li><li>◻ <strong>用户体验流程图</strong>：AI 输出的不确定性如何在前端处理？（loading / fallback / 纠错入口）</li><li>◻ <strong>灰度计划</strong>：5% 用户 → 20% → 50% → 全量，每个阶段的评估标准</li><li>◻ <strong>监控面板搭建</strong>：延迟 P50/P95/P99、调用成功率、用户满意度打分</li><li>◻ <strong>Bad Case 回收机制</strong>：用户如何反馈问题？反馈是否进入迭代闭环？</li></ul><h3 id="_1-3-持续运营节奏" tabindex="-1">1.3 持续运营节奏 <a class="header-anchor" href="#_1-3-持续运营节奏" aria-label="Permalink to &quot;1.3 持续运营节奏&quot;">​</a></h3><ul><li>○ <strong>每周</strong>：Bad Case 评审 ≥30 条，标记根因（幻觉/理解偏差/数据缺失/prompt 缺陷）</li><li>○ <strong>双周</strong>：模型效果报告（准确率/幻觉率/满意度趋势）</li><li>○ <strong>每月</strong>：推理成本复盘（是否需做蒸馏/量化）</li><li>○ <strong>每季</strong>：竞品 AI 功能扫描</li><li>○ <strong>每次发版</strong>：评估集全量回归 + 新增 edge case</li></ul><hr><h2 id="_2-跨团队沟通框架" tabindex="-1">2. 跨团队沟通框架 <a class="header-anchor" href="#_2-跨团队沟通框架" aria-label="Permalink to &quot;2. 跨团队沟通框架&quot;">​</a></h2><h3 id="_2-1-给-ceo-投资人讲-ai-roi" tabindex="-1">2.1 给 CEO / 投资人讲 AI ROI <a class="header-anchor" href="#_2-1-给-ceo-投资人讲-ai-roi" aria-label="Permalink to &quot;2.1 给 CEO / 投资人讲 AI ROI&quot;">​</a></h3><blockquote><p>CEO 不关心你用的是什么模型，只关心这玩意儿到底值不值。</p></blockquote><h4 id="核心问题" tabindex="-1">核心问题 <a class="header-anchor" href="#核心问题" aria-label="Permalink to &quot;核心问题&quot;">​</a></h4><p>CEO/投资人最常问的三个问题：</p><ol><li>&quot;AI 到底给我们带来了什么价值？&quot;</li><li>&quot;这个 ROI 怎么算？&quot;</li><li>&quot;凭什么我们要比别人多花钱做 AI？&quot;</li></ol><h4 id="价值沟通框架-三种-roi-叙事" tabindex="-1">价值沟通框架：三种 ROI 叙事 <a class="header-anchor" href="#价值沟通框架-三种-roi-叙事" aria-label="Permalink to &quot;价值沟通框架：三种 ROI 叙事&quot;">​</a></h4><p><strong>① 用户价值型</strong>（适合 toC 产品 / 增长阶段）</p><ul><li><strong>叙事角度</strong>：AI 提升了哪些用户体验指标</li><li><strong>关键指标</strong>：任务完成率 ↑、完成时间 ↓、用户满意度 ↑、NPS ↑</li><li><strong>话术模板</strong>： <ul><li>&quot;这不是一个 AI 功能，这是一个让用户效率提升 <strong>X 倍</strong>的解决方案。&quot;</li><li>&quot;用户之前完成这个任务平均需要 <strong>Y 分钟</strong>，现在只需要 <strong>Z 秒</strong>，转化率提升了 <strong>W%</strong>。&quot;</li><li>&quot;我们不是在做 chatbot，我们是在做<strong>7×24 小时的专家助手</strong>。&quot;</li></ul></li></ul><p><strong>② 成本价值型</strong>（适合 toB 产品 / 降本增效）</p><ul><li><strong>叙事角度</strong>：AI 替代/辅助了哪些人工环节</li><li><strong>关键指标</strong>：客服成本 ↓、人工处理时长 ↓、人效比 ↑、自动化率 ↑</li><li><strong>话术模板</strong>： <ul><li>&quot;当前每次人工客服成本 <strong>$Y</strong>，AI 首次解决成本 <strong>$X</strong>，差 <strong>Z 倍</strong>。&quot;</li><li>&quot;AI 自动化率从 0% 提升到 <strong>N%</strong>，相当于省了 <strong>M 个全职人力</strong>。&quot;</li><li>&quot;这不是裁员工具，这是让团队做<strong>更高价值工作</strong>的杠杆。&quot;</li></ul></li></ul><p><strong>③ 收入价值型</strong>（适合商业化阶段）</p><ul><li><strong>叙事角度</strong>：AI 功能带来了多少付费转化和收入</li><li><strong>关键指标</strong>：AI 功能付费率 ↑、ARPU ↑、付费转化率 ↑、留存 ↑</li><li><strong>话术模板</strong>： <ul><li>&quot;AI 功能上线后，付费转化率从 <strong>A%</strong> 提升到 <strong>B%</strong>，新增 MRR <strong>$C</strong>。&quot;</li><li>&quot;用户因为 AI 功能留下的比例比非 AI 用户高 <strong>D%</strong>，12 个月 LTV 高 <strong>E 倍</strong>。&quot;</li><li>&quot;当前成本 <strong>$F/用户</strong>，但给用户节约了 <strong>$G/用户</strong>的时间价值。&quot;</li></ul></li></ul><h4 id="roi-计算模板-填空即用" tabindex="-1">ROI 计算模板（填空即用） <a class="header-anchor" href="#roi-计算模板-填空即用" aria-label="Permalink to &quot;ROI 计算模板（填空即用）&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI 功能 ROI = (节省成本 + 新增收入) / (AI 成本 + 工程成本)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>节省成本 = 人工处理量 × 人工单价 × AI 替代率</span></span>
<span class="line"><span>新增收入 = AI 功能付费用户数 × 客单价 + 留存提升带来的增量收入</span></span>
<span class="line"><span>AI 成本  = 推理成本 + 标注成本 + 基础设施 + API 订阅</span></span>
<span class="line"><span>工程成本 = AI 团队人力成本分摊 + 迭代周期分摊</span></span></code></pre></div><blockquote><p><strong>避坑提示</strong>：不要只报正面数据。主动暴露风险：&quot;如果模型效果达不到预期，ROI 可能减半，我们的止损线是 XXX。&quot;</p></blockquote><h4 id="给-ceo-的汇报模板-5-分钟版" tabindex="-1">给 CEO 的汇报模板（5 分钟版） <a class="header-anchor" href="#给-ceo-的汇报模板-5-分钟版" aria-label="Permalink to &quot;给 CEO 的汇报模板（5 分钟版）&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 一句话：我们做的 AI 功能解决了什么问题，给用户/公司带来什么价值</span></span>
<span class="line"><span>2. 数据说话：上线以来核心指标变化（Before vs After）</span></span>
<span class="line"><span>3. ROI 计算：投入多少钱，省了/赚了多少钱，什么时候回本</span></span>
<span class="line"><span>4. 风险提示：最大的不确定性是什么，我们怎么应对</span></span>
<span class="line"><span>5. 下一步：接下来做什么，需要 CEO 做什么决策</span></span></code></pre></div><h3 id="_2-2-给工程师讲-pm-视角" tabindex="-1">2.2 给工程师讲 PM 视角 <a class="header-anchor" href="#_2-2-给工程师讲-pm-视角" aria-label="Permalink to &quot;2.2 给工程师讲 PM 视角&quot;">​</a></h3><h4 id="话术-1-为什么这个-prompt-这么重要" tabindex="-1">话术 1：为什么这个 Prompt 这么重要？ <a class="header-anchor" href="#话术-1-为什么这个-prompt-这么重要" aria-label="Permalink to &quot;话术 1：为什么这个 Prompt 这么重要？&quot;">​</a></h4><blockquote><p>工程师常说的话：&quot;不就是改几个字吗？效果能有多大差别？&quot;</p></blockquote><p><strong>你的回答框架：</strong></p><ul><li><strong>第一层（技术理解）</strong>：&quot;Prompt 不是&#39;改几个字&#39;，是<strong>模型的指令集</strong>。好的 prompt 能降低幻觉率 30-50%，这比换一个更大参数量模型性价比高得多。&quot;</li><li><strong>第二层（产品视角）</strong>：&quot;你知道吗？用户对这个功能的满意度，70% 取决于 prompt 质量，只有 30% 取决于模型选型。因为 prompt 决定了用户看到的第一句话、第一个回答、第一次信任。&quot;</li><li><strong>第三层（共同目标）</strong>：&quot;我们一起设计一个 prompt 版本管理系统，每次改动都跑完整评估集。你来做 prompt 工程化的架构，我来定义评估标准和用户反馈。&quot;</li><li><strong>实操建议</strong>：&quot;prompt 的每个变更都要有版本号、变更理由、评估结果。像管理代码一样管理 prompt。工具推荐：LangSmith、Weights &amp; Biases Prompts。&quot;</li></ul><h4 id="话术-2-为什么评估标准不能只看准确率" tabindex="-1">话术 2：为什么评估标准不能只看准确率？ <a class="header-anchor" href="#话术-2-为什么评估标准不能只看准确率" aria-label="Permalink to &quot;话术 2：为什么评估标准不能只看准确率？&quot;">​</a></h4><blockquote><p>工程师常说的话：&quot;准确率 98%，够了吧？&quot;</p></blockquote><p><strong>你的回答框架：</strong></p><ul><li><strong>第一层（产品视角）</strong>：&quot;准确率 98% 的意思是，每 100 个用户里有 2 个得到错误答案。对搜索引擎来说这 OK，但对<strong>金融/医疗/法律</strong>场景，2% 的错误率意味着灾难。&quot;</li><li><strong>第二层（用户视角）</strong>：&quot;用户记住的不是 98 次正确，而是那 2 次错误。错误答案带来的信任损失是指数级的。&quot;</li><li><strong>第三层（系统视角）</strong>：&quot;我们需要的是一套多维评估体系： <ul><li><strong>精确率</strong>：给出的答案中正确的比例 → 错了就是信任崩塌</li><li><strong>召回率</strong>：该覆盖的问题都覆盖了吗 → 漏了就是体验缺失</li><li><strong>拒绝率</strong>：不知道的时候能说不知道吗 → 硬答就是致命幻觉</li><li><strong>延迟 P95</strong>：95% 的请求在多长时间内返回 → 慢了就是流失</li><li><strong>用户纠错率</strong>：用户需要手动修改 AI 输出的比例 → 高了就是鸡肋&quot;</li></ul></li><li><strong>落地建议</strong>：&quot;我们建一个评估看板，把这些指标都可视化。每周过一遍 bad case，把准确率拆解成用户可感知的体验指标。&quot;</li></ul><h4 id="话术-3-怎么让工程师参与产品决策" tabindex="-1">话术 3：怎么让工程师参与产品决策？ <a class="header-anchor" href="#话术-3-怎么让工程师参与产品决策" aria-label="Permalink to &quot;话术 3：怎么让工程师参与产品决策？&quot;">​</a></h4><ul><li>&quot;你来决定<strong>用什么模型、怎么部署</strong>，但<strong>做什么、做到什么标准</strong>我们一起定。&quot;</li><li>&quot;我希望你能看到用户反馈——我给你开权限看客服记录和用户评价。&quot;</li><li>&quot;每次 bad case 评审，我不只看数据，我叫上你一起看用户说了什么。&quot;</li><li>&quot;评估集里我给你留 20% 的&#39;探索用例&#39;，你可以自己加你觉得重要的场景。&quot;</li></ul><h3 id="_2-3-给设计师讲-ai-产品交互约束" tabindex="-1">2.3 给设计师讲 AI 产品交互约束 <a class="header-anchor" href="#_2-3-给设计师讲-ai-产品交互约束" aria-label="Permalink to &quot;2.3 给设计师讲 AI 产品交互约束&quot;">​</a></h3><h4 id="设计师常说的困惑" tabindex="-1">设计师常说的困惑 <a class="header-anchor" href="#设计师常说的困惑" aria-label="Permalink to &quot;设计师常说的困惑&quot;">​</a></h4><ul><li>&quot;为什么 AI 的输出不能像普通数据一样精准？&quot;</li><li>&quot;为什么 loading 状态这么复杂？&quot;</li><li>&quot;为什么不能给用户一个&#39;确定&#39;按钮？&quot;</li></ul><h4 id="你的回答框架" tabindex="-1">你的回答框架 <a class="header-anchor" href="#你的回答框架" aria-label="Permalink to &quot;你的回答框架&quot;">​</a></h4><p><strong>第一课：AI 是不确定的，交互要为不确定性设计</strong></p><ul><li>普通产品：输入 A → 输出 B（确定的、可预期的）</li><li>AI 产品：输入 A → 输出可能是 B/C/D/E（概率性的、不可完全预期的）</li><li><strong>对设计的影响</strong>： <ul><li>不要假设 AI 输出是&quot;正确的&quot;——用户需要有验证和纠错的入口</li><li>不要假设 AI 输出是&quot;一致的&quot;——同一问题不同时间可能不同答案</li><li>不要做&quot;一次输出定终身&quot;的设计——要有编辑、重新生成、反馈机制</li></ul></li></ul><p><strong>第二课：状态设计比普通产品多一倍</strong></p><table tabindex="0"><thead><tr><th>状态</th><th>普通产品</th><th>AI 产品</th></tr></thead><tbody><tr><td>初始态</td><td>空白页面</td><td>引导示例 + 能力边界提示</td></tr><tr><td>加载态</td><td>spinner</td><td>流式输出 + 进度暗示 + 取消按钮</td></tr><tr><td>成功态</td><td>显示数据</td><td>显示 AI 输出 + 置信度标识 + 纠错入口</td></tr><tr><td>空态</td><td>&quot;暂无数据&quot;</td><td>&quot;我还不会回答这个问题，试试问别的&quot;</td></tr><tr><td>错误态</td><td>错误提示</td><td>降级方案(简化回答/转人工/重试)</td></tr><tr><td>极限态</td><td>分页展示</td><td>长回答折叠 + 关键信息高亮</td></tr></tbody></table><p><strong>第三课：交互模式的三个层次</strong></p><ul><li><strong>第一层（AI 主导）</strong>：用户说，AI 做。交互最简单，但用户控制感最弱。 <ul><li>适用：信息查询、内容总结、翻译</li><li>设计要点：输入框 + 结果显示 + &quot;不满意？重新生成&quot;按钮</li></ul></li><li><strong>第二层（人机协作）</strong>：AI 建议，用户决定。交互最复杂，但效果最好。 <ul><li>适用：文案创作、代码生成、数据分析</li><li>设计要点：AI 产出 → 用户编辑 → AI 辅助修改 → 用户确认</li></ul></li><li><strong>第三层（AI 辅助）</strong>：用户主导，AI 在旁边提供建议。 <ul><li>适用：写作辅助、设计辅助、决策支持</li><li>设计要点：保持用户主控权，AI 建议不打断用户流程</li></ul></li></ul><p><strong>第四课：给设计师的检查清单</strong></p><ul><li>☐ 用户知道 AI 的能力边界吗？（不要等用户问了才知道 AI 不会）</li><li>☐ 用户能理解 AI 的回答为什么不完美吗？（置信度/来源提示）</li><li>☐ AI 出错时，用户知道怎么纠正吗？（反馈入口放哪里）</li><li>☐ 用户能控制 AI 的&quot;温度&quot;吗？（创意度调节、详细程度调节）</li><li>☐ 加载状态有&quot;可取消&quot;选项吗？（生成到一半不满意可以直接停）</li><li>☐ 历史对话中，用户能找到之前 AI 给的答案吗？（会话存储和搜索）</li></ul><hr><h2 id="_3-ai-产品-demo-技巧" tabindex="-1">3. AI 产品 Demo 技巧 <a class="header-anchor" href="#_3-ai-产品-demo-技巧" aria-label="Permalink to &quot;3. AI 产品 Demo 技巧&quot;">​</a></h2><h3 id="_3-1-ai-demo-为什么容易翻车" tabindex="-1">3.1 AI Demo 为什么容易翻车？ <a class="header-anchor" href="#_3-1-ai-demo-为什么容易翻车" aria-label="Permalink to &quot;3.1 AI Demo 为什么容易翻车？&quot;">​</a></h3><p><strong>五大翻车原因：</strong></p><table tabindex="0"><thead><tr><th>原因</th><th>概率</th><th>典型场景</th></tr></thead><tbody><tr><td>模型输出不稳定</td><td>⭐⭐⭐⭐⭐</td><td>昨天演示正常的 prompt，今天输出完全不一样</td></tr><tr><td>幻觉不可控</td><td>⭐⭐⭐⭐</td><td>模型自信满满地说出一个错误事实</td></tr><tr><td>演示环境 vs 真实环境差异</td><td>⭐⭐⭐⭐</td><td>本地跑得好好的，现场网络慢/延迟高</td></tr><tr><td>用户输入不可控</td><td>⭐⭐⭐</td><td>投资人问了预期之外的刁钻问题</td></tr><tr><td>依赖服务不稳定</td><td>⭐⭐⭐</td><td>第三方 API 限流/宕机/版本变更</td></tr></tbody></table><h3 id="_3-2-demo-准备-——-三层防线" tabindex="-1">3.2 Demo 准备 —— 三层防线 <a class="header-anchor" href="#_3-2-demo-准备-——-三层防线" aria-label="Permalink to &quot;3.2 Demo 准备 —— 三层防线&quot;">​</a></h3><h4 id="第一层防线-多套输入方案" tabindex="-1">第一层防线：多套输入方案 <a class="header-anchor" href="#第一层防线-多套输入方案" aria-label="Permalink to &quot;第一层防线：多套输入方案&quot;">​</a></h4><ul><li><strong>Plan A</strong>：你最完美的演示场景，模型 90%+ 概率稳定输出 <ul><li>输入经过精心设计，覆盖核心价值主张</li><li>提前跑 50 次以上，确认输出质量稳定</li></ul></li><li><strong>Plan B</strong>：备选场景，与 Plan A 不同但同样能展示核心价值 <ul><li>当 Plan A 翻车时的第一替代方案</li><li>同样提前跑 50 次以上验证</li></ul></li><li><strong>Plan C</strong>：最安全、最简单的场景（哪怕展示价值不够惊艳） <ul><li>最后的兜底方案，模型输出确定性最高</li><li>可以是&quot;能跑就行&quot;的级别</li></ul></li></ul><blockquote><p><strong>铁律</strong>：每个 demo 至少准备 3 套输入方案，且每套都在演示环境中跑过至少 50 次。</p></blockquote><h4 id="第二层防线-硬编码策略-vs-真实调用" tabindex="-1">第二层防线：硬编码策略 vs 真实调用 <a class="header-anchor" href="#第二层防线-硬编码策略-vs-真实调用" aria-label="Permalink to &quot;第二层防线：硬编码策略 vs 真实调用&quot;">​</a></h4><p><strong>硬编码策略（适合高规格演示 / 投资人场）</strong></p><ul><li>提前把理想的模型输出录好 / 写好</li><li>现场演示时走&quot;模拟模式&quot;，展示的是一致的最佳效果</li><li><strong>适用场景</strong>：融资演示、重要客户签约、CEO 对外的 Keynote</li><li><strong>注意事项</strong>：必须标注&quot;模拟效果&quot;，不要误导观众以为模型已经完美</li><li><strong>伦理边界</strong>：可以展示&quot;未来能力&quot;但必须诚实说明当前阶段</li></ul><p><strong>真实调用策略（适合内部评审 / 灰度验收）</strong></p><ul><li>现场真实调用模型，展示真实效果</li><li><strong>适用场景</strong>：团队内部评审、技术选型对比、A/B 测试结果展示</li><li><strong>注意事项</strong>：做好翻车预案，坦然面对不完美</li><li><strong>最佳实践</strong>：&quot;我们来看看真实的效果 —— 好的一面和不好的一面都看&quot;</li></ul><p><strong>混合策略（推荐）</strong></p><ul><li>核心价值场景走硬编码（展示愿景）</li><li>互动环节走真实调用（展示诚实）</li><li>话术：&quot;这是我们的目标效果（硬编码），这是当前的真实水平（真实调用），差距就是我们下一步要解决的问题。&quot;</li></ul><h4 id="第三层防线-降级预案" tabindex="-1">第三层防线：降级预案 <a class="header-anchor" href="#第三层防线-降级预案" aria-label="Permalink to &quot;第三层防线：降级预案&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>模型崩了/变慢 → 降级方案执行清单（5 秒内切换）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>□ 第一步：切换到预先录制的 Demo 视频（提前准备好 3-5 分钟）</span></span>
<span class="line"><span>□ 第二步：口头描述&quot;正常情况下这里会看到……&quot;</span></span>
<span class="line"><span>□ 第三步：切换到备用模型（如 GPT-4 → GPT-3.5 / 本地小模型）</span></span>
<span class="line"><span>□ 第四步：如果所有方案都失败 —— &quot;这正是我们正在解决的问题，它展示了 AI 产品的不确定性，这也是为什么我们需要更多的资源和时间来打磨。&quot;</span></span></code></pre></div><blockquote><p><strong>心态提示</strong>：翻车不是世界末日。真诚地面对问题，解释&quot;这是我们正在解决的挑战&quot;，反而能给观众留下诚实和专业的印象。</p></blockquote><h3 id="_3-3-demo-现场-checklist" tabindex="-1">3.3 Demo 现场 Checklist <a class="header-anchor" href="#_3-3-demo-现场-checklist" aria-label="Permalink to &quot;3.3 Demo 现场 Checklist&quot;">​</a></h3><h4 id="演示前-24-小时" tabindex="-1">演示前 24 小时 <a class="header-anchor" href="#演示前-24-小时" aria-label="Permalink to &quot;演示前 24 小时&quot;">​</a></h4><ul><li>☐ <strong>环境检查</strong><ul><li>☐ 演示网络已测试（带宽 &gt; 10Mbps，延迟 &lt; 50ms）</li><li>☐ 所有 API Key 有效，没有过期</li><li>☐ 模型 endpoint 可用（不是&quot;维护中&quot;）</li><li>☐ 备用网络（手机热点/独立 5G 路由）</li></ul></li><li>☐ <strong>内容验证</strong><ul><li>☐ Plan A/B/C 各跑了 50 次，记录输出稳定性</li><li>☐ 所有计划中的 demo 输入已保存为文本（不要现场打字）</li><li>☐ 录播视频已准备好（画质 1080p，声音清晰，含字幕）</li><li>☐ fallback 回答已写好，存为本地文件</li></ul></li><li>☐ <strong>设备检查</strong><ul><li>☐ 电脑电量 100%，充电器随身</li><li>☐ 投影/投屏测试通过，字体大小可读</li><li>☐ 演示用浏览器清除了缓存和插件干扰</li><li>☐ 关掉所有通知（Slack/邮件/日历弹窗）</li></ul></li></ul><h4 id="演示前-1-小时" tabindex="-1">演示前 1 小时 <a class="header-anchor" href="#演示前-1-小时" aria-label="Permalink to &quot;演示前 1 小时&quot;">​</a></h4><ul><li>☐ 现场网络再次测试</li><li>☐ 再次跑一遍 Plan A 确认稳定</li><li>☐ 录播视频本地播放测试（不要依赖流媒体）</li><li>☐ 关闭所有无关浏览器标签和应用程序</li><li>☐ 深呼吸，心态准备好：最坏情况已有预案</li></ul><h4 id="演示中" tabindex="-1">演示中 <a class="header-anchor" href="#演示中" aria-label="Permalink to &quot;演示中&quot;">​</a></h4><ul><li>☐ <strong>开场白先降预期</strong>：&quot;AI 产品的一个特点是每次输出都不一样，我们来看看今天的运气如何。&quot;</li><li>☐ <strong>先展示价值，再展示技术</strong>：不要上来就讲模型架构</li><li>☐ <strong>操作要慢</strong>：让观众看到你输入了什么、得到了什么</li><li>☐ <strong>如果翻车</strong>：微笑 → &quot;这正是我们在解决的挑战&quot; → 切换到 Plan B</li><li>☐ <strong>控制演示范围</strong>：只演示你准备好的场景，不要即兴探索</li><li>☐ <strong>留 30% 时间做 Q&amp;A</strong>：但 Q&amp;A 环节不做实时 demo 演示</li></ul><h3 id="_3-4-常见翻车案例与预防措施" tabindex="-1">3.4 常见翻车案例与预防措施 <a class="header-anchor" href="#_3-4-常见翻车案例与预防措施" aria-label="Permalink to &quot;3.4 常见翻车案例与预防措施&quot;">​</a></h3><h4 id="案例-1-模型返回错误答案" tabindex="-1">案例 1：模型返回错误答案 <a class="header-anchor" href="#案例-1-模型返回错误答案" aria-label="Permalink to &quot;案例 1：模型返回错误答案&quot;">​</a></h4><p><strong>场景</strong>：给投资人演示 AI 客服，问&quot;我们公司去年的营收是多少&quot;，模型说了一个错误的数字。</p><p><strong>根因</strong>：</p><ul><li>RAG 检索到的知识文档版本不对/太旧</li><li>模型无视检索结果，凭训练数据回答（即&quot;检索增强&quot;没生效）</li><li>prompt 没有约束&quot;如果不知道请说不知道&quot;</li></ul><p><strong>预防措施</strong>：</p><ul><li>✅ prompt 里明确写：&quot;优先使用检索到的知识，如果文档中没有信息，请明确说&#39;我的知识库中没有这个信息&#39;&quot;</li><li>✅ 演示前测试那些&quot;模型容易出错&quot;的问题，针对性加固</li><li>✅ 准备一个&quot;全对&quot;的演示路径和一个&quot;模型说不知道&quot;的演示路径（后者反而能展示诚实）</li><li>✅ fallback 回答就写在旁边的纸上：&quot;以下是准备好的回答……&quot;</li></ul><h4 id="案例-2-现场网络延迟过高" tabindex="-1">案例 2：现场网络延迟过高 <a class="header-anchor" href="#案例-2-现场网络延迟过高" aria-label="Permalink to &quot;案例 2：现场网络延迟过高&quot;">​</a></h4><p><strong>场景</strong>：在客户公司会议室演示，Wi-Fi 信号差，模型返回需要 30 秒。</p><p><strong>根因</strong>：</p><ul><li>没有提前测试演示环境网络</li><li>没有降级方案</li><li>模型推理时间没有做超时处理</li></ul><p><strong>预防措施</strong>：</p><ul><li>✅ 提前到现场测试网络，或自备 5G 热点</li><li>✅ 准备好 3-5 分钟录播视频（展示完整流畅的体验）</li><li>✅ 模型设置超时时间（建议 10 秒），超时自动展示 fallback</li><li>✅ 流式输出（streaming）先显示第一个 token 给用户&quot;有东西在出来了&quot;的感觉</li></ul><h4 id="案例-3-用户输入预期之外的-prompt" tabindex="-1">案例 3：用户输入预期之外的 Prompt <a class="header-anchor" href="#案例-3-用户输入预期之外的-prompt" aria-label="Permalink to &quot;案例 3：用户输入预期之外的 Prompt&quot;">​</a></h4><p><strong>场景</strong>：CEO 在 demo 现场突然问：&quot;让它写一首诗讽刺我们竞品。&quot;</p><p><strong>根因</strong>：</p><ul><li>没有对演示输入做范围限定</li><li>模型的安全对齐被触发，拒绝回答（反而尴尬）</li><li>或者更糟 —— 模型真的写了一首讽刺诗（合规灾难）</li></ul><p><strong>预防措施</strong>：</p><ul><li>✅ 演示前明确告知观众：&quot;我准备了几个场景，我们先按这些来走。&quot;</li><li>✅ 准备好回应框架：&quot;这是个有趣的问题，不过我今天的 demo 主要聚焦 XX 场景，会后我们可以专门测试这个方向。&quot;</li><li>✅ 如果被强迫输入，先确认输入安全：&quot;让我看看怎么处理这个……&quot;（给自己争取切换到备用方案的时间）</li><li>✅ 最好的预防：演示界面限定输入范围（预置的示例问题，不让自定义输入）</li></ul><h4 id="案例-4-模型突然-失忆-或风格突变" tabindex="-1">案例 4：模型突然&quot;失忆&quot;或风格突变 <a class="header-anchor" href="#案例-4-模型突然-失忆-或风格突变" aria-label="Permalink to &quot;案例 4：模型突然&quot;失忆&quot;或风格突变&quot;">​</a></h4><p><strong>场景</strong>：同样的问题，上周 demo 回答得很好，今天模型像换了个人。</p><p><strong>根因</strong>：</p><ul><li>模型版本被服务商悄悄更新了（API 模型常见问题）</li><li>system prompt 被其他人不小心改了</li><li>温度/超参设置被重制</li></ul><p><strong>预防措施</strong>：</p><ul><li>✅ 锁定模型版本（不要用&quot;最新版&quot;，用固定版本号如 gpt-4-0613）</li><li>✅ 演示前 checklist 中加一条：检查 system prompt 和超参设置</li><li>✅ 把 system prompt 和参数配置写成可复用的配置文件</li><li>✅ 如果必须用 unpinned 版本，提前测试新版本的输出变化</li></ul><h4 id="案例-5-依赖的第三方服务不可用" tabindex="-1">案例 5：依赖的第三方服务不可用 <a class="header-anchor" href="#案例-5-依赖的第三方服务不可用" aria-label="Permalink to &quot;案例 5：依赖的第三方服务不可用&quot;">​</a></h4><p><strong>场景</strong>：RAG 系统依赖的向量数据库挂了，AI 无法检索知识。</p><p><strong>根因</strong>：</p><ul><li>没有做服务依赖的降级设计</li><li>没有离线缓存</li></ul><p><strong>预防措施</strong>：</p><ul><li>✅ RAG 系统设计时加上本地缓存层（向量缓存 + 知识缓存）</li><li>✅ 降级方案：缓存不可用时，模型退化为纯 LLM 模式（只靠训练知识回答）</li><li>✅ 演示前检查所有依赖服务的健康状态</li><li>✅ 准备一个&quot;纯 LLM&quot;模式的演示路径</li></ul><h3 id="_3-5-录播-vs-直播-选型决策" tabindex="-1">3.5 录播 vs 直播：选型决策 <a class="header-anchor" href="#_3-5-录播-vs-直播-选型决策" aria-label="Permalink to &quot;3.5 录播 vs 直播：选型决策&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>录播（Pre-recorded）</th><th>直播（Live Demo）</th></tr></thead><tbody><tr><td><strong>推荐场景</strong></td><td>融资演示、Keynote、客户签约、高规格对外展示</td><td>内部评审、技术选型、灰度验收、团队 sync</td></tr><tr><td><strong>核心优势</strong></td><td>100% 可控，零翻车风险，可后期制作</td><td>真实可信，能展示交互细节，现场问答</td></tr><tr><td><strong>核心风险</strong></td><td>不够真实，观众怀疑是&quot;假 AI&quot;</td><td>翻车概率 30-50%，不可控因素多</td></tr><tr><td><strong>准备时间</strong></td><td>2-3 天（拍摄 + 剪辑 + 字幕）</td><td>1-2 天（测试 + 预案 + 排练）</td></tr><tr><td><strong>最佳时长</strong></td><td>3-5 分钟</td><td>10-15 分钟</td></tr><tr><td><strong>翻车应对</strong></td><td>不存在翻车问题</td><td>必须准备完整降级预案</td></tr><tr><td><strong>观众信任</strong></td><td>中（会被质疑真实性）</td><td>高（翻车但诚实反而加分）</td></tr><tr><td><strong>技术深度展示</strong></td><td>难（只能展示结果）</td><td>易（可以展示交互过程）</td></tr></tbody></table><p><strong>决策树：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Demo 场景是什么？</span></span>
<span class="line"><span>├── 对外的（投资/客户/大会演讲）</span></span>
<span class="line"><span>│   ├── 建议录播（3分钟精剪版）</span></span>
<span class="line"><span>│   └── + 会后安排直播 Q&amp;A 环节</span></span>
<span class="line"><span>├── 对内的（团队/评审/老板汇报）</span></span>
<span class="line"><span>│   ├── 建议直播（展示真实能力）</span></span>
<span class="line"><span>│   ├── + 录播备份兜底</span></span>
<span class="line"><span>│   └── + 准备好&quot;翻车也是个亮点&quot;的心态</span></span>
<span class="line"><span>└── 混合的（部分展示用录播，互动用直播）</span></span>
<span class="line"><span>    └── 最佳方案：录播展示&quot;愿景&quot;，直播展示&quot;现状&quot;</span></span></code></pre></div><h4 id="录播制作-checklist" tabindex="-1">录播制作 Checklist <a class="header-anchor" href="#录播制作-checklist" aria-label="Permalink to &quot;录播制作 Checklist&quot;">​</a></h4><ul><li>☐ 脚本撰写：说人话，不讲术语，30 秒内展示核心价值</li><li>☐ 录制工具：Screen Studio / OBS，60fps，4K 录制（输出 1080p）</li><li>☐ 音频质量：领夹麦 + 安静环境，背景噪音 &lt; 40dB</li><li>☐ 后期处理：关键步骤加放大镜/高亮效果，视频底部加字幕</li><li>☐ 免责声明：末尾标注&quot;展示效果基于实际产品，可能因网络环境和模型状态有所不同&quot;</li><li>☐ 备用格式：MP4（通用）+ 链接（在线播放），两种都准备好</li></ul><h4 id="直播呈现技巧" tabindex="-1">直播呈现技巧 <a class="header-anchor" href="#直播呈现技巧" aria-label="Permalink to &quot;直播呈现技巧&quot;">​</a></h4><ul><li>☐ 开场先展示&quot;这是真的&quot;：现场输入几个字，让观众看到实时输出</li><li>☐ 慢节奏操作：每次输入后等 2-3 秒再说话，让观众消化</li><li>☐ 口头标注：&quot;这是我的屏幕，我正在输入……可以看到模型在实时生成……&quot;</li><li>☐ 互动技巧：&quot;谁想上来试试？&quot;（选 1-2 个观众，但控制输入范围）</li><li>☐ 出现小问题直接说：语气轻松地解释&quot;这里模型有点调皮了&quot;</li><li>☐ 出现大问题直接切换：不要挣扎，立刻换 Plan B</li></ul><hr><h2 id="附录-工具推荐" tabindex="-1">附录：工具推荐 <a class="header-anchor" href="#附录-工具推荐" aria-label="Permalink to &quot;附录：工具推荐&quot;">​</a></h2><h3 id="prompt-管理-langsmith、w-b-prompts、agenta" tabindex="-1">Prompt 管理：LangSmith、W&amp;B Prompts、Agenta <a class="header-anchor" href="#prompt-管理-langsmith、w-b-prompts、agenta" aria-label="Permalink to &quot;Prompt 管理：LangSmith、W&amp;B Prompts、Agenta&quot;">​</a></h3><h3 id="模型评估-giskard、deepeval、langfuse" tabindex="-1">模型评估：Giskard、DeepEval、LangFuse <a class="header-anchor" href="#模型评估-giskard、deepeval、langfuse" aria-label="Permalink to &quot;模型评估：Giskard、DeepEval、LangFuse&quot;">​</a></h3><h3 id="demo-制作-screen-studio、obs-studio、arcade" tabindex="-1">Demo 制作：Screen Studio、OBS Studio、Arcade <a class="header-anchor" href="#demo-制作-screen-studio、obs-studio、arcade" aria-label="Permalink to &quot;Demo 制作：Screen Studio、OBS Studio、Arcade&quot;">​</a></h3><h3 id="成本监控-helicone、langsmith、arize-ai" tabindex="-1">成本监控：Helicone、LangSmith、Arize AI <a class="header-anchor" href="#成本监控-helicone、langsmith、arize-ai" aria-label="Permalink to &quot;成本监控：Helicone、LangSmith、Arize AI&quot;">​</a></h3><hr><p><em>版本：v1.0 | 更新于 2026.05</em></p>`,134)])])}const q=l(s,[["render",n]]);export{p as __pageData,q as default};
